import { esc, options, money, icon } from '../ui.js';
import { statuses } from '../data.js';
export default function dashboard({state,ui}) {
 const rows=state.records.filter(r=>!ui.dashboardOwner||r.owner===ui.dashboardOwner);const counts=statuses.map(s=>rows.filter(r=>r.status===s).length);
 const tabs=['מכירות','הצעות מחיר','לידים שלא הוקצו','לידים בטיפול','משימות','פגישות','פניות'];const chosen=ui.dashboardTab||tabs[0];
 const visible=chosen==='לידים בטיפול'?rows.filter(r=>r.status==='בטיפול'):chosen==='לידים שלא הוקצו'?rows.filter(r=>r.status==='חדש'):rows.slice(0,6);
 return `<div class="dashboard-layout"><section class="dashboard-work"><div class="native-tabs" role="tablist" aria-label="מבט על">${tabs.map(t=>`<button role="tab" aria-selected="${chosen===t}" data-action="dashboard-tab" data-tab="${t}">${t}</button>`).join('')}</div><div class="card"><div class="toolbar"><label class="field grow"><span>מנהל לקוח</span><select data-field="dashboardOwner" id="dashboard-owner">${options(['','צוות 1','צוות 2','צוות 3'],ui.dashboardOwner)}</select></label><a href="#records" class="outline small">הצגת הכול</a></div><h2 class="panel-caption">${chosen}</h2><div class="table-wrap"><table><thead><tr><th>שם</th><th>סטטוס</th><th>מנהל לקוח</th><th>סכום</th></tr></thead><tbody>${visible.map(r=>`<tr><td><button class="row-link" data-action="edit-record" data-id="${r.id}">${esc(r.name)}</button></td><td>${esc(r.status)}</td><td>${esc(r.owner)}</td><td>${money(r.amount)}</td></tr>`).join('')||'<tr><td colspan="4">אין נתונים להצגה</td></tr>'}</tbody></table></div><p class="muted">נתוני הדגמה · ${visible.length} רשומות</p></div></section><aside class="dashboard-insights"><div class="kpis">${[['לקוחות',''+rows.length,'list'],['סך מכירות',money(rows.reduce((a,r)=>a+r.amount,0)),'chart'],['בטיפול',''+counts[1],'clock'],['הושלמו',''+counts[2],'board']].map(([label,value,i])=>`<div class="kpi"><div><span>${label}</span><strong>${value}</strong></div>${icon(i)}</div>`).join('')}</div><section class="card"><h2 class="panel-caption">התפלגות לפי סטטוס</h2><div class="bars" role="img" aria-label="${statuses.map((s,i)=>s+': '+counts[i]).join(', ')}">${statuses.map((s,i)=>`<div class="bar" style="height:${Math.max(1,counts[i]/Math.max(1,...counts)*145)}px"><b>${counts[i]}</b><span>${s}</span></div>`).join('')}</div><p class="muted chart-legend">● רשומות בסינון הנבחר</p></section></aside></div>`;
}
